140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        HttpHeaders headers = new HttpHeaders();
148	        Pet pet = petMapper.toPet(petFieldsDto);
149	        owner.setId(ownerId);
150	        pet.setOwner(owner);
151	        pet.getType().setName(null);
152	        this.clinicService.savePet(pet);
153	        PetDto petDto = petMapper.toPetDto(pet);
154	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
155	            .buildAndExpand(pet.getId()).toUri());
156	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
157	    }
